const DEFAULT_CODE_LANGUAGE = ''
const CODE_BLOCK_LANGUAGES = { '': 'Plain text', js: 'JavaScript', ts: 'TypeScript', tsx: 'TSX', bash: 'Shell' }
const EMPTY_PLACEHOLDERS: readonly ActionPlaceholder[] = []
const EMPTY_REPOSITORY_FILES: readonly string[] = []

export interface MarkdownEditorHandle {
    flush(): boolean
    getMarkdown(): string
    setMarkdown(markdown: string): void
}

interface MarkdownEditorPresentationProps {
    attachmentHandler?: (files: File[], insertMarkdown: AttachmentMarkdownInserter) => Promise<void>
    diffMarkdown?: string
    flushOnBlur?: boolean
    /** Omit format toolbar entirely. */
    hideToolbar?: boolean
    /** Hide built-in attachment control while retaining attachment drops. */
    hideAttachmentControl?: boolean
    imagePasteHandler?: MarkdownImagePasteHandler
    /** Set false when containing surface owns Ctrl+F behavior. */
    localTextSearch?: boolean
    overlayContainer?: HTMLElement | null
    placeholders?: readonly ActionPlaceholder[]
    readOnly?: boolean
    toolbarContents?: () => ReactNode
    viewMode?: ViewMode
}

interface MarkdownEditorDataSourceProps extends MarkdownEditorPresentationProps {
    binding: MarkdownBindingKind
    dataSource: MarkdownDataSource
    draft?: never
    historyStore: MarkdownDocumentHistoryStore
    markdown?: never
    onChange?: never
    onDirtyChange?: never
    onLiveChange?: never
}

interface MarkdownEditorLocalProps extends MarkdownEditorPresentationProps {
    binding?: never
    dataSource?: never
    draft?: never
    historyStore?: never
    markdown: string
    onChange: (markdown: string) => void
    onDirtyChange?: (dirty: boolean) => void
    onLiveChange?: (markdown: string) => void
}

interface MarkdownEditorDraftProps extends MarkdownEditorPresentationProps {
    binding?: never
    dataSource?: never
    draft: MarkdownDraft
    historyStore?: never
    markdown?: never
    onChange?: (markdown: string) => void
    onDirtyChange?: (dirty: boolean) => void
    onLiveChange?: (markdown: string) => void
}

type MarkdownEditorProps = MarkdownEditorDataSourceProps | MarkdownEditorLocalProps | MarkdownEditorDraftProps

interface MarkdownDocumentSnapshot {
    target: MarkdownDocumentTarget | null
    markdown: string
}

interface MarkdownProcessingError {
    error: string
}

function initialDocument(props: MarkdownEditorProps): MarkdownDocumentSnapshot {
    if (props.draft) return { target: null, markdown: props.draft.getSnapshot() }
    if (!props.dataSource) return { target: null, markdown: props.markdown }

    const target = props.dataSource.getActiveTarget(props.binding)
    return { target, markdown: target ? props.dataSource.getMarkdown(target) : '' }
}

/** Reusable MDXEditor surface with local-buffer and persisted data-source modes. */
export const MarkdownEditor = forwardRef<MarkdownEditorHandle, MarkdownEditorProps>(function MarkdownEditor(props, ref) {
    const {
        flushOnBlur = false,
        attachmentHandler,
        diffMarkdown,
        hideAttachmentControl = false,
        hideToolbar = false,
        imagePasteHandler,
        localTextSearch = true,
        overlayContainer,
        placeholders = EMPTY_PLACEHOLDERS,
        readOnly = false,
        toolbarContents: customToolbarContents,
        viewMode,
    } = props
    const dataSource = props.dataSource
    const binding = props.binding
    const historyStore = props.historyStore
    const draft = props.draft
    const { snapshot } = useProjectState()
    const repositoryFiles = snapshot?.repositoryFiles ?? EMPTY_REPOSITORY_FILES
    const initialDocumentRef = useRef<MarkdownDocumentSnapshot | null>(null)
    if (!initialDocumentRef.current) initialDocumentRef.current = initialDocument(props)
    const initialDocumentSnapshot = initialDocumentRef.current
    const { markdownContentSx, mode } = useAppTheme()
    const editorRef = useRef<MDXEditorMethods>(null)
    const activeTargetRef = useRef(initialDocumentSnapshot.target)
    const latestMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const lastEmittedMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const dirtyBaselineEstablishedRef = useRef(false)
    const missingEditorReportedRef = useRef(false)
    const replacingMarkdownRef = useRef(false)
    const onChangeRef = useRef(props.onChange)
    const onDirtyChangeRef = useRef(props.onDirtyChange)
    const onLiveChangeRef = useRef(props.onLiveChange)
    const applyPendingDocumentChangeRef = useRef<() => void>(() => undefined)
    onChangeRef.current = props.onChange
    onDirtyChangeRef.current = props.onDirtyChange
    onLiveChangeRef.current = props.onLiveChange

    const setDirty = useCallback((dirty: boolean) => {
        onDirtyChangeRef.current?.(dirty)
    }, [])

    const flush = useCallback(() => {
        if (latestMarkdownRef.current === lastEmittedMarkdownRef.current) return true

        const activeTarget = activeTargetRef.current
        if (dataSource && binding) {
            if (!activeTarget) return false
            const committed = dataSource.commit(binding, activeTarget, latestMarkdownRef.current)
            if (!committed) return false
        } else {
            onChangeRef.current?.(latestMarkdownRef.current)
        }
        lastEmittedMarkdownRef.current = latestMarkdownRef.current
        setDirty(false)
        queueMicrotask(() => applyPendingDocumentChangeRef.current())

        return true
    }, [binding, dataSource, setDirty])

    const prepareDocumentSwitch = useCallback((detail: ActiveMarkdownDocumentChangedDetail, nextMarkdown: string) => {
        if (detail.discard) lastEmittedMarkdownRef.current = latestMarkdownRef.current
        if (!flush()) return null

        const currentMarkdown = latestMarkdownRef.current
        activeTargetRef.current = detail.target
        latestMarkdownRef.current = nextMarkdown
        lastEmittedMarkdownRef.current = nextMarkdown
        setDirty(false)

        return currentMarkdown
    }, [flush, setDirty])

    const completeDocumentSwitch = useCallback((normalizedMarkdown: string) => {
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        setDirty(false)
    }, [setDirty])

    const getMarkdown = useCallback(() => editorRef.current?.getMarkdown() ?? latestMarkdownRef.current, [])
    const getTarget = useCallback(() => activeTargetRef.current, [])

    const replaceMarkdown = useCallback((markdown: string) => {
        replacingMarkdownRef.current = true
        editorRef.current?.setMarkdown(markdown)
        replacingMarkdownRef.current = false
    }, [])

    const replaceDraftMarkdown = useCallback((markdown: string) => {
        replaceMarkdown(markdown)
        latestMarkdownRef.current = markdown
        lastEmittedMarkdownRef.current = markdown
        setDirty(false)
    }, [replaceMarkdown, setDirty])

    const setPendingDocumentChangeRetry = useCallback((retry: () => void) => {
        applyPendingDocumentChangeRef.current = retry
    }, [])

    const historyPluginConfig = useMemo(() => historyStore && binding && dataSource
        ? {
            binding,
            completeDocumentSwitch,
            dataSource,
            getTarget,
            getMarkdown,
            historyStore,
            prepareDocumentSwitch,
            replaceMarkdown,
            setPendingDocumentChangeRetry,
        }
        : null, [
        binding,
        completeDocumentSwitch,
        dataSource,
        getTarget,
        getMarkdown,
        historyStore,
        prepareDocumentSwitch,
        replaceMarkdown,
        setPendingDocumentChangeRetry,
    ])

    useEffect(() => {
        if (!editorRef.current) {
            if (!missingEditorReportedRef.current) {
                missingEditorReportedRef.current = true
                dialogService.error(new Error('Cannot baseline markdown before editor is mounted'), {fallbackMessage: 'Markdown editor could not be initialized'})
            }
            return
        }

        const normalizedMarkdown = editorRef.current.getMarkdown()
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        dirtyBaselineEstablishedRef.current = true
    }, [])

    useEffect(() => {
        const unregister = registerMarkdownEditorStage(flush)

        return () => {
            unregister()
            flush()
        }
    }, [flush])

    useImperativeHandle(ref, () => ({
        flush,
        getMarkdown: () => latestMarkdownRef.current,
        setMarkdown: (markdown: string) => {
            replaceMarkdown(markdown)
            latestMarkdownRef.current = markdown
            lastEmittedMarkdownRef.current = markdown
            setDirty(false)
        },
    }), [flush, replaceMarkdown, setDirty])

    const handleEditorChange = useCallback((markdown: string) => {
        if (replacingMarkdownRef.current || latestMarkdownRef.current === markdown) return

        latestMarkdownRef.current = markdown
        if (!dirtyBaselineEstablishedRef.current) return
        setDirty(markdown !== lastEmittedMarkdownRef.current)
        onLiveChangeRef.current?.(markdown)
        draft?.edit(markdown)
        const activeTarget = activeTargetRef.current
        if (dataSource && binding && activeTarget) dataSource.edit(binding, activeTarget, markdown)
    }, [binding, dataSource, draft, setDirty])

    const handleEditorError = useCallback(({ error }: MarkdownProcessingError) => {
        dialogService.error(new Error(error), { fallbackMessage: 'Markdown could not be parsed' })
    }, [])

    const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
        if (!flushOnBlur || event.currentTarget.contains(event.relatedTarget)) return
        flush()
    }

    const insertMarkdown = useCallback((markdown: string) => {
        if (!editorRef.current) throw new Error('Markdown editor is not mounted')
        editorRef.current.insertMarkdown(markdown)
    }, [])

    useMarkdownDraft(draft, insertMarkdown, replaceDraftMarkdown)

    const getSelectionMarkdown = useCallback(() => editorRef.current?.getSelectionMarkdown() ?? '', [])

    const attachFiles = useCallback((files: File[]) => {
        if (!attachmentHandler || readOnly || files.length === 0) return
        void attachmentHandler(files, insertMarkdown).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: 'Files could not be attached' })
        })
    }, [attachmentHandler, insertMarkdown, readOnly])

    const handleDragOverCapture = (event: DragEvent<HTMLDivElement>) => {
        if (!attachmentHandler || readOnly || !event.dataTransfer.types.includes('Files')) return
        event.preventDefault()
        event.stopPropagation()
    }

    const handleDropCapture = (event: DragEvent<HTMLDivElement>) => {
        if (!attachmentHandler || readOnly || !event.dataTransfer.types.includes('Files')) return
        event.preventDefault()
        event.stopPropagation()
        attachFiles([...event.dataTransfer.files])
    }

    const toolbarContents = useCallback(() => (
        <>
            {!hideToolbar ? (
                customToolbarContents?.()
                ?? (
                    <MarkdownFormatToolbarControls
                        overlayContainer={overlayContainer}
                        placeholders={placeholders}
                        readOnly={readOnly}
                    />
                )
            ) : null}
            {attachmentHandler && !hideAttachmentControl ? (
                <MarkdownAttachmentControl disabled={readOnly} onFiles={attachFiles} />
            ) : null}
        </>
    ), [
        attachFiles, attachmentHandler, customToolbarContents, hideAttachmentControl, hideToolbar, overlayContainer,
        placeholders, readOnly,
    ])
    const editorSx = {
        ...markdownContentSx,
        '& .mdxeditor-toolbar': { bgcolor: 'background.paper', position: 'sticky', top: 0, zIndex: 1 },
    }
    const historyPlugin = historyPluginConfig ? markdownDocumentHistoryPlugin(historyPluginConfig) : null
    const plugins = [
        headingsPlugin(),
        listsPlugin(),
        quotePlugin(),
        thematicBreakPlugin(),
        linkPlugin(),
        linkDialogPlugin(),
        imagePlugin(),
        tablePlugin(),
        codeBlockPlugin({ defaultCodeBlockLanguage: DEFAULT_CODE_LANGUAGE }),
        codeMirrorPlugin({ codeBlockLanguages: CODE_BLOCK_LANGUAGES }),
        markdownShortcutPlugin(),
        plainMarkdownPlugin(),
        ...(viewMode ? [diffSourcePlugin({ diffMarkdown: diffMarkdown ?? '', viewMode })] : []),
        ...(!hideToolbar || (attachmentHandler && !hideAttachmentControl) ? [toolbarPlugin({ toolbarContents })] : []),
        markdownPlaceholderPlugin({ overlayContainer, placeholders }),
        markdownFileSearchPlugin({ overlayContainer, repositoryFiles }),
        ...(localTextSearch ? [markdownLocalTextSearchPlugin({ overlayContainer })] : []),
        markdownPastePlugin({ getSelectionMarkdown, imagePasteHandler, insertMarkdown, readOnly }),
        ...(historyPlugin ? [historyPlugin] : []),
    ]

    return (
        <Box
            data-sticky-toolbar
            onBlur={handleBlur}
            onDragOverCapture={handleDragOverCapture}
            onDropCapture={handleDropCapture}
            sx={editorSx}
        >
            <MDXEditor
                className={mode === 'dark' ? 'dark-theme' : 'light-theme'}
                contentEditableClassName="mdxeditor-content"
                markdown={initialDocumentSnapshot.markdown}
                onChange={handleEditorChange}
                onError={handleEditorError}
                overlayContainer={overlayContainer}
                plugins={plugins}
                readOnly={readOnly}
                ref={editorRef}
                suppressHtmlProcessing
                suppressSharedHistory={!!historyStore}
            />
        </Box>
    )
})

import { createCommand } from 'lexical'

/** Opens local text search for the active Markdown editor. */
export const OPEN_MARKDOWN_LOCAL_TEXT_SEARCH_COMMAND = createCommand<void>()

import SearchOutlined from '@mui/icons-material/SearchOutlined'
import { IconButton, Tooltip } from '@mui/material'
import { activeEditor$, useCellValue } from '@mdxeditor/editor'
import { OPEN_MARKDOWN_LOCAL_TEXT_SEARCH_COMMAND } from './markdown_local_text_search_command'

/** Opens local visible-text search for the active Markdown editor. */
export function MarkdownLocalTextSearchToolbarControl() {
    const activeEditor = useCellValue(activeEditor$)

    const handleOpen = () => {
        activeEditor?.dispatchCommand(OPEN_MARKDOWN_LOCAL_TEXT_SEARCH_COMMAND, undefined)
    }

    return (
        <Tooltip title="Find text">
            <span>
                <IconButton
                    aria-label="Find text"
                    disabled={!activeEditor}
                    onClick={handleOpen}
                    size="small"
                >
                    <SearchOutlined fontSize="small" />
                </IconButton>
            </span>
        </Tooltip>
    )
}

import SearchOutlined from '@mui/icons-material/SearchOutlined'
import { Box, IconButton, InputAdornment, Popover, TextField, ToggleButton, Tooltip } from '@mui/material'
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext'
import { useCellValue } from '@mdxeditor/editor'
import { COMMAND_PRIORITY_HIGH, KEY_DOWN_COMMAND } from 'lexical'
import {
    useCallback,
    useEffect,
    useState,
    type ChangeEvent,
    type KeyboardEvent as ReactKeyboardEvent,
} from 'react'
import { useDialogError } from '../hooks/use_dialog_error'
import {
    getMarkdownSearchSeed,
    getMarkdownSearchSelectionEnd,
    selectMarkdownTextMatch,
} from './markdown_local_text_search'
import { OPEN_MARKDOWN_LOCAL_TEXT_SEARCH_COMMAND } from './markdown_local_text_search_command'
import { markdownLocalTextSearchConfig$ } from './markdown_local_text_search_config_cell'

function isOpenSearchShortcut(event: KeyboardEvent) {
    return event.ctrlKey && !event.altKey && !event.metaKey && event.key.toLowerCase() === 'f'
}

/** Editor-local search keyboard handling and popup. */
export function MarkdownLocalTextSearchPlugin() {
    const config = useCellValue(markdownLocalTextSearchConfig$)
    const [editor] = useLexicalComposerContext()
    const [activeCaseSensitive, setActiveCaseSensitive] = useState(false)
    const [activeTerm, setActiveTerm] = useState<string | null>(null)
    const [draftCaseSensitive, setDraftCaseSensitive] = useState(false)
    const [draftTerm, setDraftTerm] = useState('')
    const [open, setOpen] = useState(false)
    const [searchOrigin, setSearchOrigin] = useState(0)
    const rootElement = editor.getRootElement()
    const configError = config ? null : new Error('Cannot register Markdown local text search without configuration')
    useDialogError(configError, 'Local text search is unavailable')

    const closeSearch = useCallback(() => {
        setOpen(false)
    }, [])

    const openSearch = useCallback(() => {
        const selectedText = getMarkdownSearchSeed(editor)
        setSearchOrigin(getMarkdownSearchSelectionEnd(editor))
        if (selectedText) setDraftTerm(selectedText)
        setOpen(true)
        return true
    }, [editor])

    const selectNextMatch = useCallback(() => {
        if (!activeTerm) return
        const offset = getMarkdownSearchSelectionEnd(editor)
        selectMarkdownTextMatch(editor, activeTerm, offset, activeCaseSensitive)
    }, [activeCaseSensitive, activeTerm, editor])

    const submitSearch = useCallback(() => {
        if (!draftTerm) return
        setActiveTerm(draftTerm)
        setActiveCaseSensitive(draftCaseSensitive)
        selectMarkdownTextMatch(editor, draftTerm, searchOrigin, draftCaseSensitive)
    }, [draftCaseSensitive, draftTerm, editor, searchOrigin])

    const handleKeyDown = useCallback((event: KeyboardEvent) => {
        if (isOpenSearchShortcut(event)) {
            event.preventDefault()
            openSearch()
            return true
        }
        if (event.key !== 'F3') return false

        event.preventDefault()
        selectNextMatch()
        return true
    }, [openSearch, selectNextMatch])

    useEffect(() => {
        const unregisterOpen = editor.registerCommand(
            OPEN_MARKDOWN_LOCAL_TEXT_SEARCH_COMMAND,
            openSearch,
            COMMAND_PRIORITY_HIGH,
        )
        const unregisterKeyDown = editor.registerCommand(KEY_DOWN_COMMAND, handleKeyDown, COMMAND_PRIORITY_HIGH)

        return () => {
            unregisterOpen()
            unregisterKeyDown()
        }
    }, [editor, handleKeyDown, openSearch])

    const handleTermChange = (event: ChangeEvent<HTMLInputElement>) => {
        setDraftTerm(event.target.value)
    }

    const handleCaseToggle = () => {
        setDraftCaseSensitive((current) => !current)
    }

    const handleInputKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Escape') {
            event.preventDefault()
            closeSearch()
            return
        }
        if (event.key === 'Enter') {
            event.preventDefault()
            submitSearch()
            return
        }
        if (event.key !== 'F3') return

        event.preventDefault()
        selectNextMatch()
    }

    return (
        <Popover
            anchorEl={rootElement}
            anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
            anchorPosition={rootElement ? undefined : { left: 0, top: 0 }}
            anchorReference={rootElement ? 'anchorEl' : 'anchorPosition'}
            container={config?.overlayContainer ?? undefined}
            onClose={closeSearch}
            open={open}
            slotProps={{
                paper: {
                    sx: {
                        border: '1px solid',
                        borderColor: 'divider',
                        borderRadius: '14px',
                    },
                },
            }}
            transformOrigin={{ horizontal: 'right', vertical: 'top' }}
        >
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.75, p: 1, width: 260 }}>
                <TextField
                    autoFocus
                    fullWidth
                    onChange={handleTermChange}
                    onKeyDown={handleInputKeyDown}
                    placeholder="Find text"
                    size="small"
                    slotProps={{
                        htmlInput: { 'aria-label': 'Find text' },
                        input: {
                            startAdornment: (
                                <InputAdornment position="start">
                                    <Tooltip title="Search">
                                        <IconButton aria-label="Search" edge="start" onClick={submitSearch} size="small">
                                            <SearchOutlined fontSize="small" />
                                        </IconButton>
                                    </Tooltip>
                                </InputAdornment>
                            ),
                        },
                    }}
                    value={draftTerm}
                />
                <Tooltip title="Match case">
                    <ToggleButton
                        aria-label="Match case"
                        onClick={handleCaseToggle}
                        selected={draftCaseSensitive}
                        size="small"
                        value="case-sensitive"
                    >
                        Aa
                    </ToggleButton>
                </Tooltip>
            </Box>
        </Popover>
    )
}

import {
    $createRangeSelection,
    $getRoot,
    $getSelection,
    $isElementNode,
    $isRangeSelection,
    $isTextNode,
    $setSelection,
    type LexicalEditor,
    type NodeKey,
    type PointType,
} from 'lexical'

export interface MarkdownTextMatch {
    end: number
    start: number
}

interface MarkdownTextSegment {
    end: number
    key: NodeKey
    start: number
}

interface MarkdownSearchDocument {
    segments: MarkdownTextSegment[]
    text: string
}

function createSearchDocument(): MarkdownSearchDocument {
    const root = $getRoot()
    const text = root.getTextContent()
    let nextOffset = 0
    const segments = root.getAllTextNodes().flatMap((node) => {
        const nodeText = node.getTextContent()
        if (!nodeText) return []

        const start = text.indexOf(nodeText, nextOffset)
        if (start < 0) throw new Error(`Markdown search could not map text node ${node.getKey()}`)
        const end = start + nodeText.length
        nextOffset = end

        return [{ end, key: node.getKey(), start }]
    })

    return { segments, text }
}

function normalizeSearchText(value: string, caseSensitive: boolean) {
    return caseSensitive ? value : value.toLocaleLowerCase()
}

/** Finds next match at or after offset, wrapping once to document start. */
export function findMarkdownTextMatch(
    text: string,
    term: string,
    offset: number,
    caseSensitive: boolean,
): MarkdownTextMatch | null {
    if (!term) return null

    const searchableText = normalizeSearchText(text, caseSensitive)
    const searchableTerm = normalizeSearchText(term, caseSensitive)
    const startOffset = Math.min(Math.max(offset, 0), text.length)
    const laterMatch = searchableText.indexOf(searchableTerm, startOffset)
    const start = laterMatch >= 0 ? laterMatch : searchableText.indexOf(searchableTerm)

    return start < 0 ? null : { end: start + term.length, start }
}

function pointTextOffset(point: PointType, document: MarkdownSearchDocument) {
    if (point.type === 'text') {
        const segment = document.segments.find(({ key }) => key === point.key)
        return segment ? segment.start + point.offset : 0
    }

    const pointNode = point.getNode()
    const nextChild = 'getChildAtIndex' in pointNode ? pointNode.getChildAtIndex(point.offset) : null
    const nextTextKey = $isTextNode(nextChild)
        ? nextChild.getKey()
        : $isElementNode(nextChild) ? nextChild.getAllTextNodes()[0]?.getKey() : undefined
    const nextSegment = document.segments.find(({ key }) => key === nextTextKey)
    if (nextSegment) return nextSegment.start

    const pointTextKeys = new Set($isElementNode(pointNode)
        ? pointNode.getAllTextNodes().map((node) => node.getKey())
        : [])
    const lastSegment = document.segments.findLast(({ key }) => pointTextKeys.has(key))
    return lastSegment?.end ?? 0
}

function currentSelectionEnd(document: MarkdownSearchDocument) {
    const selection = $getSelection()
    if (!$isRangeSelection(selection)) return 0

    const points = selection.getStartEndPoints()
    return points ? pointTextOffset(points[1], document) : 0
}

function matchPoints(match: MarkdownTextMatch, segments: MarkdownTextSegment[]) {
    const startSegment = segments.find(({ end, start }) => match.start >= start && match.start < end)
    const endSegment = segments.find(({ end, start }) => match.end > start && match.end <= end)
    if (!startSegment || !endSegment) return null

    return {
        anchor: { key: startSegment.key, offset: match.start - startSegment.start },
        focus: { key: endSegment.key, offset: match.end - endSegment.start },
    }
}

/** Reads current Lexical selection end as flattened visible-text offset. */
export function getMarkdownSearchSelectionEnd(editor: LexicalEditor) {
    return editor.getEditorState().read(() => currentSelectionEnd(createSearchDocument()))
}

/** Reads non-empty selected visible text without Markdown delimiters. */
export function getMarkdownSearchSeed(editor: LexicalEditor) {
    return editor.getEditorState().read(() => {
        const selection = $getSelection()
        return $isRangeSelection(selection) && !selection.isCollapsed() ? selection.getTextContent() : ''
    })
}

/** Selects one match without changing editor content or history. */
export function selectMarkdownTextMatch(
    editor: LexicalEditor,
    term: string,
    offset: number,
    caseSensitive: boolean,
) {
    let selectedKey: NodeKey | null = null
    let selectedMatch: MarkdownTextMatch | null = null

    editor.update(() => {
        const document = createSearchDocument()
        const match = findMarkdownTextMatch(document.text, term, offset, caseSensitive)
        if (!match) return

        const points = matchPoints(match, document.segments)
        if (!points) return

        const selection = $createRangeSelection()
        selection.anchor.set(points.anchor.key, points.anchor.offset, 'text')
        selection.focus.set(points.focus.key, points.focus.offset, 'text')
        $setSelection(selection)
        selectedKey = points.anchor.key
        selectedMatch = match
    }, {
        discrete: true,
        onUpdate: () => {
            if (selectedKey) editor.getElementByKey(selectedKey)?.scrollIntoView?.({ block: 'nearest' })
        },
    })

    return selectedMatch
}

import { createCommand } from 'lexical'

/** Opens local text search for the active Markdown editor. */
export const OPEN_MARKDOWN_LOCAL_TEXT_SEARCH_COMMAND = createCommand<void>()

import { addComposerChild$, realmPlugin } from '@mdxeditor/editor'
import {
    markdownLocalTextSearchConfig$,
    type MarkdownLocalTextSearchConfig,
} from './markdown_local_text_search_config_cell'
import { MarkdownLocalTextSearchPlugin } from './markdown_local_text_search_plugin'

/** Connects local visible-text search to an MDXEditor Lexical composer. */
export const markdownLocalTextSearchPlugin = realmPlugin<MarkdownLocalTextSearchConfig>({
    init(realm, params) {
        if (!params) throw new Error('Markdown local text-search plugin requires parameters')

        realm.register(markdownLocalTextSearchConfig$)
        realm.pub(markdownLocalTextSearchConfig$, params)
        realm.pub(addComposerChild$, MarkdownLocalTextSearchPlugin)
    },
    update(realm, params) {
        if (!params) throw new Error('Markdown local text-search plugin requires parameters')

        realm.pub(markdownLocalTextSearchConfig$, params)
    },
})

