    $createRangeSelection,
    $createTextNode,
    $getRoot,
    $getSelection,
    $isRangeSelection,
    $setSelection,
    createEditor,
    type LexicalEditor,
} from 'lexical'
import { describe, expect, it } from 'vitest'
